let rightPressed = false;
let leftPressed = false;

//Handle all key down
const keyDownHandler = (e) => {
  if (e.key == "Right" || e.key == "ArrowRight"){
    rightPressed = true;
  }
  if (e.key == "Left" || e.key == "ArrowLeft"){
    leftPressed = true;
  }
}

//Handle all key up
const keyUpHandler = (e) => {
  if (e.key == "Right" || e.key == "ArrowRight"){
    rightPressed = false;
  }
  if (e.key == "Left" || e.key == "ArrowLeft"){
    leftPressed = false;
  }
}

document.addEventListener("keydown", keyDownHandler, false);
document.addEventListener("keyup", keyUpHandler, false);

const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

let playerWidth = 30;
let playerHeight = 60;
let playerX = canvas.width/2 - playerWidth /2;
let playerY = 400;

let circleRadius = 15;
let maxTimer = 10;
let timer = 300;
let fallingSpeed = 8;
let playerSpeed = 8;
let score = 0;
let scoreCount = 0;

let circles = [];


const createCircle = (x, y) => {
  return {x: x, y: y};
}

const spawnFalling = () => {
  let x = Math.floor(Math.random() * 551);
  let y = -20;
  let newCircle = createCircle(x, y);

  circles.push(newCircle);
}


const drawAndMoveCircles = () => {
  for (let i = 0; i < circles.length; i++){
    let circle = circles[i];
    circle.y += fallingSpeed;



    ctx.beginPath();
    ctx.arc(circle.x, circle.y, circleRadius, 0, Math.PI*2, false);
    ctx.stroke();
    ctx.closePath();

    if (circle.y > canvas.height + circleRadius){
      circles.splice(i, 1);
    }
  }
}

const playerHit = () => {
  for (let i = 0; i < circles.length; i++){
    let circle = circles[i];



    let distX = Math.abs(playerX + (playerWidth / 2) - circle.x);
    let distY = Math.abs(playerY + (playerHeight / 2) - circle.y);

    if(distX < (playerWidth / 2) + circleRadius && distY < (playerHeight / 2) + circleRadius){
      return true;
    } else{
      return false;
    }
  }
}

//main draw function, calls itself until the player loses
const draw = () => {
  ctx.clearRect(0,0, canvas.width, canvas.height);

  if(timer > 200){
    ctx.font = "30px Arial";
    ctx.fillStyle = "black";
    ctx.textAlign = "center";
    ctx.fillText("Game Starting in 3...", canvas.width/2, 100);
  } else if (timer > 100) {
    ctx.font = "30px Arial";
    ctx.fillStyle = "black";
    ctx.textAlign = "center";
    ctx.fillText("Game Starting in 2...", canvas.width/2, 100);
  } else if (timer > 10) {
    ctx.font = "30px Arial";
    ctx.fillStyle = "black";
    ctx.textAlign = "center";
    ctx.fillText("Game Starting in 1...", canvas.width/2, 100);
  }

  ctx.textAlign = "center";
  ctx.fillStyle = "black";
  ctx.font = "20px Arial";
  ctx.fillText("Score: " + score, 450, 480);

  ctx.fillStyle = "blue"
  ctx.fillRect(playerX, playerY, playerWidth, playerHeight);

  drawAndMoveCircles();

  if (rightPressed && playerX < canvas.width){
    playerX += playerSpeed;
  }
  if (leftPressed && playerX > 0){
    playerX -= playerSpeed;
  }

  if (playerHit()){
    ctx.font = "30px Arial";
    ctx.textAlign = "center";
    ctx.fillText("You Lose", canvas.width/2, 100);
  } else {
    window.requestAnimationFrame(draw);

    timer -= 1;
    if (timer <= 0){
      scoreCount += 1;
      if (scoreCount >= 5){
        score += 1;
        scoreCount = 0;
      }
      timer = maxTimer;
      spawnFalling();
    }
  }
}

//function calls
window.requestAnimationFrame(draw);

