// Create the classic arcade game asteroids, complete with full 2d motion! You control a spaceship which can move around the canvas, and spinning asteroids are speeding at you. You can break the asteroids by shooting them, which breaks them in half, and gives you a point.

let rightPressed = false;
let leftPressed = false;
let upPressed = false;

let cooldownTimer = 0;
let score = 0;

//setup player triangle



let player = {x: 100, y: 100, rotation: 0, totalRotation: 0};
let playerTriangle = [[10,10], [0,-15], [-10, 10]];
let circles = [];

const createCircle = () => {
  return {x: 0, y: 0, heading: 90, size: 50};
}

const createBullet = (xPos, yPos, playerHeading) => {
  return {x: xPos, y: yPos, heading: playerHeading, alive: true};
}

//Handle all key down
const keyDownHandler = (e) => {
  if (e.key == "d"){
    rightPressed = true;
  }
  if (e.key == "a"){
    leftPressed = true;
  }
  if(e.key == "w"){
    upPressed = true;
  }
  if(cooldownTimer == 0 && e.key == " " || e.key == "f" ){
    Fire();
    cooldownTimer = 10;
  }
}

//Handle all key up
const keyUpHandler = (e) => {
  if (e.key === "d") {
    rightPressed = false;
  }
  if (e.key == "a"){
    leftPressed = false;
  }
  if(e.key == "w"){
    upPressed = false;
  }
}


document.addEventListener("keydown", keyDownHandler, false);
document.addEventListener("keyup", keyUpHandler, false);

const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');


//Handle bullet firing
const Fire = () => {
  let dir = player.totalRotation - 90;
  let moveBullet;
  let bullet = createBullet(player.x, player.y, player.heading);

  window.requestAnimationFrame(moveBullet = function(){
    bullet.x += Math.cos(convertToRadians(dir)) * 5;
    bullet.y += Math.sin(convertToRadians(dir)) * 5;

    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 10, 0, Math.PI*2, false);
    ctx.fillStyle = "black";
    ctx.fill();
    ctx.closePath();

    //Loop through all the circles and check if any hit the bullet
    for (let i = 0; i < circles.length; i++){
      let circle = circles[i];
      if (Math.abs(bullet.x - circle.x) < (circle.size + 10) && Math.abs(bullet.y - circle.y) < (circle.size + 10) && bullet.alive) {

        bullet.alive = false;
        let halfRadius = circle.size / 2;

        //If still big enough, push 2 new circles of half size into its location with random degrees
        if (halfRadius > 10){
          let newX = circles[i].x;
          let newY = circles[i].y;
          for(let j = 0; j < 2; j++){
            let dir = Math.floor(Math.random() * 361);
            let splitCircle = createCircle();
            splitCircle.heading = dir;
            splitCircle.x = newX;
            splitCircle.y = newY;
            splitCircle.size = halfRadius;
            circles.push(splitCircle);
          }
        }

        score += 1;
        circles.splice(i, 1);
      }
    } 
    if(bullet.x < 560 && bullet.y < 510 && bullet.x > -10 && bullet.y > -10 && bullet.alive){
      window.requestAnimationFrame(moveBullet);
    }
  });
}


//rotates an X coordinate around an origin by a number of degrees
const rotateX = (originalX, originalY, angleOfChange) => {
  let tempPoint = (originalX * (Math.cos(angleOfChange)) + originalY * (Math.sin(angleOfChange)));
  if (tempPoint < 0.0001 && tempPoint > -0.0001){
    tempPoint = 0;
  }
  return tempPoint;
}

//rotates a Y coordinate around an origin by a number of degrees
const rotateY = (originalX, originalY, angleOfChange) => {
  let tempPoint = -originalX * Math.sin(angleOfChange)  +  originalY * (Math.cos(angleOfChange));
  if (tempPoint < 0.0001 && tempPoint > -0.0001) {
    tempPoint = 0;
  }
  return tempPoint;
}

//converts degrees into radians
const convertToRadians = (angle) => {
  return angle * (Math.PI / 180);
}


//copies a 2d array into a deep copy of itself
function copyPoints(originalPoints){
  let newList = [];
  for (let i = 0; i < originalPoints.length; i++){
    let partialList = [];
    for (let j = 0; j < originalPoints[i].length; j++){
      partialList.push(originalPoints[i][j]);
    }
    newList.push(partialList);
  }
  return newList;
}


//calculates the new points for a shape by rotating them by an angle of change
const calculatePoints = (angleOfChange, startingValues) => {
  let newPoints = copyPoints(startingValues);
  for (let i = 0; i < startingValues.length; i++){
    newPoints[i][0] = rotateX(startingValues[i][0], startingValues[i][1], angleOfChange);
    newPoints[i][1] = rotateY(startingValues[i][0], startingValues[i][1], angleOfChange);
  }
  return newPoints;
}


//draws a shape using the 2d array format for its points
const drawShape = (pointValues, middleX, middleY) => {
  if(pointValues.length > 1){
    ctx.beginPath();
    ctx.moveTo(middleX + pointValues[0][0], middleY + pointValues[0][1]);
    for(let i = 0; i < pointValues.length; i++){
      ctx.lineTo(middleX + pointValues[i][0], middleY + pointValues[i][1]);
    }
    ctx.lineTo(middleX + pointValues[0][0], middleY + pointValues[0][1]);
    ctx.fill();
    ctx.closePath();
   }
}

//spawns one circle in a random location and adds it to the circles list
const spawnCircle = () => {
  let circle = createCircle();
  let spawnSide = Math.floor(Math.random() * 4);

  if (spawnSide == 0){
    circle.x = Math.floor(Math.random() * 501);
    circle.y = -50;
    circle.heading = 90;
  }
  else if (spawnSide == 1){
    circle.x = Math.floor(Math.random() * 501);
    circle.y = 550;
    circle.heading = -90;
  }
  else if (spawnSide == 2){
    circle.x = -50;
    circle.y = Math.floor(Math.random() * 501);
    circle.heading = 0;
  }
  else{
    circle.x = 550;
    circle.y = Math.floor(Math.random() * 501);
    circle.heading = 180;
  }
  circle.heading += Math.floor(Math.random() * 180) - 90;
  circles.push(circle);
}


//draws all the circles and moves them, handling player collision
const drawAndMoveCircles = () => {
  for (let i = 0; i < circles.length; i++){
    let circle = circles[i];

    circle.x += Math.cos(convertToRadians(circle.heading)) * 2;
    circle.y += Math.sin(convertToRadians(circle.heading)) * 2;

    if (circle.x < -50){
      circle.x = 550;
    }
    if (circle.x > 600){
      circle.x = -50;
    }
    if (circle.y < -50){
      circle.y = 550;
    }
    if (circle.y > 550){
      circle.y = -50;
    }

    ctx.beginPath();
    ctx.arc(circle.x, circle.y, circle.size, 0, Math.PI*2, false);
    ctx.stroke();
    ctx.closePath();

    if(Math.abs(player.x - circle.x) < 5 + circle.size && Math.abs(player.y - circle.y) < 5 + circle.size){
      return false;
    }
  }
  return true;
}

canvas.width = 550;
canvas.height = 500;

const draw = () => {
  ctx.clearRect(0,0, canvas.width, canvas.height);

  let playerAlive = drawAndMoveCircles();

  drawShape(playerTriangle, player.x, player.y);

  //Rotation of the shape is CCW, rotation of the vector for movement is CW
  if (rightPressed){
    player.rotation -= 5;
    player.totalRotation += 5;
  }
  if (leftPressed){
    player.rotation += 5;
    player.totalRotation -= 5;
  }
  if(upPressed){
      player.x += Math.cos(convertToRadians(player.totalRotation - 90));
      player.y += Math.sin(convertToRadians(player.totalRotation - 90));
  }
  playerTriangle = calculatePoints(convertToRadians(player.rotation), playerTriangle);
  player.rotation = 0;

  if(cooldownTimer > 0){
    cooldownTimer -= 1;
  }

  ctx.font = "20px Arial";
  ctx.fillText("Score: " + score, 450, 480);

  if(playerAlive){
    window.requestAnimationFrame(draw);
  } else {
    ctx.font = "30px Arial";
    ctx.textAlign = "center";
    ctx.fillText("You Lose", canvas.width/2, 100);
  }
}

//function calls
window.requestAnimationFrame(draw);
setInterval(spawnCircle, 5000);

