// Draw an animated starfield! White stars should cascade down a black canvas and create an artistic pattern.

// Define the starfield object
const starfield = {
	fps: 30,
	canvas: null,
	width: 0,
	height: 0,
	minVelocity: 15,
	maxVelocity: 30,
	starsCount: 100,
	intervalId: 0
};

// Initializes the starfield
const makeStarfield = (containerDiv) => {
	// Store the div.
	starfield.containerDiv = containerDiv;
	starfield.width = window.innerWidth;
	starfield.height = window.innerHeight;

	//	Create the canvas.
	let canvas = document.createElement("canvas");
	containerDiv.appendChild(canvas);
	starfield.canvas = canvas;
	starfield.canvas.width = starfield.width;
	starfield.canvas.height = starfield.height;
};

starfield.start = () => {
	// Create the stars. We want to use a range based for loop here to make sure we're indexing the right objects.
	let stars = [];
	for (let i = 0; i < starfield.starsCount; i++) {
		stars[i] = makeStar(
			Math.random() * starfield.width,
			Math.random() * starfield.height,
			Math.random() * 3 + 1,
			Math.random() * (starfield.maxVelocity - starfield.minVelocity) +
				starfield.minVelocity
		);
	}

	starfield.stars = stars;

	// Start the timer.
	starfield.intervalId = setInterval(function () {
		starfield.update();
		starfield.draw();
	}, 1000 / starfield.fps);
};

starfield.update = () => {
	let dt = 1 / starfield.fps;
	starfield.stars.forEach((star, index) => {
		star.y += dt * star.velocity;
		//	If the star has moved from the bottom of the screen, spawn it at the top.
		if (star.y > starfield.height) {
			starfield.stars[index] = makeStar(
				Math.random() * starfield.width,
				0,
				Math.random() * 3 + 1,
				Math.random() * (starfield.maxVelocity - starfield.minVelocity) +
					starfield.minVelocity
			);
		}
	});
};

const makeStar = (x, y, size, velocity) => {
	return { x, y, size, velocity };
};

starfield.draw = () => {
	// Get the drawing context.
	let ctx = starfield.canvas.getContext("2d");

	// Draw the background.
	ctx.fillStyle = "#000000";
	ctx.fillRect(0, 0, starfield.width, starfield.height);

	// Draw stars.
	ctx.fillStyle = "#ffffff";

	starfield.stars.forEach((star) => {
		ctx.fillRect(star.x, star.y, star.size, star.size);
	});
};

let container = document.getElementById("container");
makeStarfield(container);
starfield.start();

// Credits: Adapted from https://www.codeproject.com/Articles/642499/Learn-JavaScript-Part-1-Create-a-Starfield

